from typing import TypedDict, Annotated
from operator import add
from langgraph.graph import StateGraph, START, END
from langgraph.checkpoint.memory import MemorySaver

class State(TypedDict):
    count: Annotated[list[str], add]

def tick(state: State) -> dict:
    return {"count": [f"tick {len(state['count']) + 1}"]}

def build_app():
    g = StateGraph(State)
    g.add_node("tick", tick)
    g.add_edge(START, "tick")
    g.add_edge("tick", END)
    # the checkpointer is what persists state between invokes
    return g.compile(checkpointer=MemorySaver())

def run_twice(app, thread_id: str):
    config = {"configurable": {"thread_id": thread_id}}
    app.invoke({"count": []}, config)          # first call
    result = app.invoke({"count": []}, config)  # SAME id -> continues
    return result["count"]

from typing import TypedDict, Annotated
from operator import add
from langgraph.graph import StateGraph, START, END
from langgraph.checkpoint.memory import MemorySaver

class State(TypedDict):
    turns: Annotated[list[str], add]   # accumulates

def respond(state: State) -> dict:
    return {"turns": [f"turn {len(state['turns']) + 1}"]}

def build():
    g = StateGraph(State)
    g.add_node("respond", respond)
    g.add_edge(START, "respond")
    g.add_edge("respond", END)
    return g.compile(checkpointer=MemorySaver())  # persistence

def chat(app, msg: str, conv_id: str):
    # stable thread_id tied to the conversation, never random
    cfg = {"configurable": {"thread_id": conv_id}}
    return app.invoke({"turns": [f"user: {msg}"]}, cfg)["turns"]

if __name__ == "__main__":
    app = build()
    chat(app, "hi", "c1")
    print(len(chat(app, "again", "c1")))     # same conv -> grows
    print(len(chat(app, "new", "c2")))       # different conv -> fresh
